// Calculate and log hourly energy cost
var power = ReadDouble("Building.Energy.TotalPower_kW");
var cost = power * 0.12; // EUR/kWh
Log($"Current power: {power:F1} kW, estimated cost: {cost:F2} EUR/h");

// Reduce lighting and HVAC after hours
var hour = DateTime.Now.Hour;
if (hour >= 22 || hour < 6) {
    Write("Building.Lighting.Floor1.Zone1_Level", 10.0);
    Write("Building.Lighting.Floor1.Zone2_Level", 10.0);
    Write("Building.HVAC.AHU1.SupplyFanSpeed", 30.0);
}
